"""OCTA303 vFable: model_v7 for the repository's tools (code written by Claude, Anthropic).

The reference model is tools/octa303/model_v7/ (O3_MODEL_V7=DIR names another copy).  This module
  * builds its C kernel (o3k.c) with the system's C compiler (CC, else cc: gcc or Apple clang) into
    out/octa303/libo3k-<hash of the sources>.so, once, and points o3model.py at it (O3K_LIB);
  * imports o3model.py without writing bytecode beside it (nothing built is left inside tools/);
  * reads the committed tables (o3tab.h / o3tab.s): the single truth, never regenerated by a test.
"""
import os, sys, re, json, math, hashlib, shutil, subprocess, importlib.util

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.normpath(os.path.join(HERE, '..', '..'))
MODEL = os.environ.get('O3_MODEL_V7') or os.path.join(HERE, 'model_v7')
LAWS = os.path.join(MODEL, 'leggi_A_v5.json')
SOURCES = ('o3k.c', 'o3int.h')
CFLAGS = ['-O2', '-ffp-contract=off', '-shared', '-fPIC']     # no fused multiply-add on any target


def lib_path():
    if not os.path.isfile(os.path.join(MODEL, 'o3k.c')):
        sys.exit('o3m7: the model is not at %s (set O3_MODEL_V7)' % MODEL)
    cc = os.environ.get('CC') or shutil.which('cc') or shutil.which('gcc') or shutil.which('clang')
    if not cc:
        sys.exit('o3m7: no C compiler (set CC, or install one: on macOS `xcode-select --install`)')
    h = hashlib.sha256()
    for f in SOURCES: h.update(open(os.path.join(MODEL, f), 'rb').read())
    h.update(' '.join(CFLAGS).encode())
    try:                                                       # one kernel per compiler (CC=gcc / CC=clang apart)
        h.update(subprocess.run([cc, '--version'], capture_output=True, text=True).stdout.encode())
    except OSError:
        sys.exit('o3m7: the C compiler %s does not run' % cc)
    h.update(cc.encode())
    out = os.path.join(ROOT, 'out', 'octa303')
    so = os.path.join(out, 'libo3k-%s.so' % h.hexdigest()[:12])
    if not os.path.isfile(so):
        os.makedirs(out, exist_ok=True)
        tmp = so + '.%d.tmp' % os.getpid()
        r = subprocess.run([cc] + CFLAGS + ['-I', MODEL, '-o', tmp, os.path.join(MODEL, 'o3k.c'), '-lm'],
                           capture_output=True, text=True)
        if r.returncode:
            sys.exit('o3m7: building the model kernel with %s failed:\n%s' % (cc, r.stderr))
        os.replace(tmp, so)
    return so


def load():
    """-> the o3model module (its kernel built from the model's sources)"""
    os.environ['O3K_LIB'] = lib_path()
    dwb = sys.dont_write_bytecode; sys.dont_write_bytecode = True
    try:
        spec = importlib.util.spec_from_file_location('o3model_v7', os.path.join(MODEL, 'o3model.py'))
        m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    finally:
        sys.dont_write_bytecode = dwb
    return m


def committed():
    """-> (tables {name: [ints]} in o3tab.h's order, scalars {O3S_name: int}, the layout [(name, n)], int16 names)"""
    h = open(os.path.join(MODEL, 'o3tab.h')).read()
    sc = {k: int(v) for k, v in re.findall(r'#define (O3S_\w+) \((-?\d+)\)', h)}
    tabs, layout, w16 = {}, [], set()
    for ty, nm, n, body in re.findall(r'static const (int16_t|int32_t) O3T_(\w+)\[(\d+)\] = \{(.*?)\};', h, re.S):
        v = [int(x) for x in re.findall(r'-?\d+', body)]
        assert len(v) == int(n), nm
        tabs[nm] = v; layout.append((nm, int(n)))
        if ty == 'int16_t': w16.add(nm)
    return tabs, sc, layout, w16


def blob():
    """the table blob the C kernel takes (o3int.h's layout = o3tab.h's order)"""
    tabs, _, layout, _ = committed()
    return [x for nm, _ in layout for x in tabs[nm]]


FS = 44100.0
C3_HZ = 130.8128                     # TUNE 0 = C3, standard tuning (A4 = 440 Hz): the shell's owners, 13 Nov 2026


def s32(v):
    v &= 0xFFFFFFFF
    return v - (1 << 32) if v & 0x80000000 else v


def q31(x):                          # o3k.c q31(): floor, capped at 0.99999999 and -1
    if x > 0.99999999: x = 0.99999999
    if x < -1.0: x = -1.0
    return int(math.floor(x * 2147483648.0))


def derived(sc):
    """the engine's O3E_* constants.  The per-sample ones are what o3k.c core() computes from the laws in doubles,
    with the same expressions: + - * / and floor only (IEEE-exact on every platform, no libm)."""
    M = json.load(open(LAWS))
    GhD = math.pi * M['fh'] / FS; GhD = GhD / (1.0 + GhD)
    d = dict(O3E_GH=q31(GhD), O3E_DUTY=int(math.floor(M['duty'] * 4294967296.0)) & 0xFFFFFFFF,
             O3E_LEAK=q31(M['leak']), O3E_SQLEV=q31(M['sqlev']))
    assert M['sawdir'] > 0, 'the engine has the rising saw only (sawdir 1)'
    for j in range(4):                                   # u = octd + LR_j - U0, as one add (mod 2^32 the same)
        d['O3E_LRU%d' % j] = s32(sc['O3S_LR%d' % j] - sc['O3S_U0'])
    d['O3E_ACCVH'] = sc['O3S_ACCV'] >> 6                 # (ACCV * k) >> 6 = (ACCV >> 6) k + (((ACCV & 63) k) >> 6)
    d['O3E_ACCVL'] = sc['O3S_ACCV'] & 63
    d['O3E_INCC3'] = int(math.floor(C3_HZ / FS * 4294967296.0))
    d['O3E_O2MAX'] = int(17.9 * 16777216)                # o3int.h TRCK: (int32_t)(17.9 * 16777216)
    assert 2 * (d['O3E_INCC3'] << 3) < (1 << 30), 'inc0 << 1 must stay below 2^31 at +3 octaves'
    # stage B (o3k.c core()): the soft clips' S and input factors (OVDR's by the knob: model_v7/o3tab.h KOV), the
    # per-sample one-poles, +D's rest value.  sclip_s(v, kin, S) runs in 32 bits as q = v (kin >> 16) +
    # fmul(v, (kin & 0xffff) << 15) with |v| clamped to SQ2 / (kin >> 16) + 1 first (the clip is flat past it).
    SQ2 = 1518500249                                     # o3k.c SQ2_Q30
    r2 = math.sqrt(2.0)                                  # M_SQRT2: both the correctly rounded double
    So_d = 4.0 * 1048576.0 / (2.0 * r2 / 3.0)
    Sm_d = 314572.0 / (2.0 * r2 / 3.0)
    So, Sm = int(math.floor(So_d + 0.5)), int(math.floor(Sm_d + 0.5))
    kuc = int(math.floor(70368744177664.0 / So_d + 0.5))
    kmu = int(math.floor(70368744177664.0 / Sm_d + 0.5))
    d['O3E_SQ2'] = SQ2
    for nm, k in (('KUC', kuc), ('KMU', kmu)):
        d['O3E_%sH' % nm] = k >> 16
        d['O3E_%sL' % nm] = (k & 0xFFFF) << 15
        d['O3E_%sV' % nm] = SQ2 // (k >> 16) + 1
        assert (d['O3E_%sV' % nm] * k) >> 16 < (1 << 31) and d['O3E_%sV' % nm] * (k >> 16) > SQ2
    d['O3E_SO2'], d['O3E_SM2'] = 2 * So, 2 * Sm
    assert 2 * So < (1 << 31)
    def tptq(f):
        g = math.pi * f / FS
        return q31(g / (1.0 + g))
    d['O3E_GM'], d['O3E_GF5'], d['O3E_GD6'], d['O3E_GDC'] = tptq(150.0), tptq(5.0), tptq(6000.0), tptq(8.0)
    x = 125829 << 10                                     # +D's rest value: o3k.c dp_clip(0)
    fm = lambda a, b: s32((a * b) >> 31)
    x2 = fm(x, x); x3 = fm(x2, x)
    d['O3E_DP0'] = (x - fm(x3, 1431655765)) >> 10
    return d
